-- ============================================================================
-- سؤال واحد، ثلاث إجابات — وأكثرها قراءةً تُحصّل مالاً لا يستحقّه أحد
-- ============================================================================
-- البند الثالث من أمر العمل: كم يدفع حامل الكملك مقابل العلاج فعلاً؟
--
-- أجاب الموقع بثلاث إجابات يستحيل صدقها معاً:
--
--   sgk-gss-health-insurance-turkey-2026، 152 قراءة، أعلى صفحاته الصحية:
--     «السوريون تحت الحماية المؤقتة — من 1 يناير 2026 لازم يسجلوا ويدفعوا
--      الاشتراكات» + «الشهري 1,982 … السنوي حوالي 23,782 ليرة»
--   gss-premium-2026-foreigners-syrians، 11 قراءة، والخطأ في العنوان نفسه:
--     «السوريون تحت الكملك: 0 ل.ت — مستثنون … مجاناً»
--   syria-temporary-protection-health-2026، 53 قراءة، ومصدرها ملف الجريدة
--   الرسمية: حصة مشاركة عند الخدمة، بلا قسط وبلا تسجيل.
--
-- والثالثة وحدها هي الصحيحة، وهي التي لا يكاد أحد يقرؤها.
--
-- ── ما أثبته التحقّق ────────────────────────────────────────────────────
--
-- أربعة عشر وكيلاً راجعوا كل رقم على mevzuat.gov.tr وresmigazete.gov.tr
-- وsgk.gov.tr وseddk.gov.tr، ثم هاجم كلَّ نتيجةٍ مراجعٌ مستقلّ:
--
--   * كلمة «prim» (قسط) ترد صفر مرّة في لائحة الحماية المؤقتة، و«tescil»
--     (تسجيل) صفر مرّة. وعبارة «geçici koruma» ترد صفر مرّة في القانون 5510.
--     والمادة 60/1-(g) — صاحبة مبلغ 1,981.80 — نصّها «vatandaşlar»: مواطنون.
--     فمبلغ 23,782 ليرة سنوياً الذي تُحصّله صفحة الـ152 قراءة لا يستحقّه أحدٌ
--     من جمهورها.
--   * والقرار الرئاسي 10658 (ج.ر 33091، 28/11/2025، نافذ 1/1/2026) عدّل
--     المادة 27 ولا شيء غيرها، فحوّل حصة المشاركة من «قد تُؤخذ» (alınabilir)
--     بمقدارٍ تحدّده الوزارة، إلى «تُؤخذ» (alınır) بمقادير بلاغ التطبيق
--     الصحي. فالقول «لم يتغيّر شيء» خطأ أيضاً.
--   * والمقادير تغيّرت مرّةً ثانية في 1 تموز/يوليو 2026 (ج.ر 33297). فأرقام
--     26 و60 ليرة التي نشرها هذا الموقع في تموز — وكانت صحيحة يوم نُشرت —
--     صارت منذ خمسة أسابيع نصف النافذ تقريباً.
--
-- وهذه الأخيرة هي الفائدة التي تستحقّ الحفظ: صفحة الشرح على موقع SGK نفسه
-- ما زالت تعرض اليوم 26 و60 ليرة و«5 ليرات». نطاقٌ رسمي، ومظهرٌ حديث، وخطأ
-- بالنصف. والذي يحسم هو النصّ المدمج على mevzuat.gov.tr بوسمه الداخلي
-- «(Değişik:RG-1/7/2026-33297)» الذي يربط كل رقم بالأداة التي قرّرته. كون
-- المصدر على نطاق حكومي ليس كونه سارياً — وهذه ثاني مرّة في هذا التدقيق
-- يكون فيها مصدرٌ أوّلي قديماً بطريقة لا يكشفها فحص نطاق ولا رمز حالة.
--
-- وتكرّر الفخّان المعروفان وعُولجا بدل أن يُحسبا غياباً للدليل: قرار الجريدة
-- الرسمية صورة JBIG2 بلا طبقة نصّ، وصفحة التعديل الذي حمل الجدول الجديد
-- تعرضه صورةً — فجلبٌ عاديٌّ للأداة المُنشِئة يعيد بنية المواد ولا يعيد رقماً
-- واحداً بالليرة.
--
-- ── ما يصحّحه هذا الملف ─────────────────────────────────────────────────
--
--   152  sgk-gss-health-insurance-turkey-2026   أُعيدت بناءً على «من أنت؟»
--   353  syrians-statistics-turkey-2026         «علاج … مجانية» في الرسوم
--    53  syria-temporary-protection-health-2026 صحيحة، وبلا رقم واحد
--    27  أسعار-السيكورتا                        جدول أسعار أقدم بخمس سنوات
--    12  syria-registration-freeze-turkey       «الصحة … مجانية» في الرسوم
--    11  gss-premium-2026-foreigners-syrians    العنوان نفسه يقول «مستثنون»
--    11  mhrs-guide-syrians-arabs-2026          «الكشف مجاني للسوريين»
--     5  kimlik-ilac-recete-katilim-payi        26/60 نُسخت في 1/7/2026
--     4  work-injury-is-kazasi-foreigners-2026  «ستعالجك مجاناً (الكملك ساري)»
--          و consultant_scenarios: daily-mhrs-booking و work-sgk
--          و family-pregnancy-birth
--
-- ولا رقم هنا من مصدر ثانوي. وحيث يحدّد القانون التغطية ولا يحدّد السعر —
-- التأمين الخاص للإقامة — يُنشر الحدّ الأدنى للتغطية ويُقال صراحةً إنّه لا
-- سعر مقرَّراً، بدل أن يُطبع رقم.
--
-- آمن لإعادة التشغيل. لا يحتاج نشر شيفرة.
-- ============================================================================

UPDATE articles SET
    details = '<p>هذه الصفحة تجيب سؤالاً واحداً: <strong>كم تدفع أنت مقابل العلاج في تركيا سنة 2026؟</strong> والجواب يختلف اختلافاً كاملاً بحسب الوثيقة التي تحملها، ولذلك تبدأ من هناك لا من الأرقام.</p><h2>أولاً: ثلاثة أشياء مختلفة يخلط بينها الجميع</h2><p>معظم الارتباك في هذا الموضوع سببه أنّ ثلاثة مبالغ مختلفة تُذكر باسم واحد هو «التأمين»:</p><ul><li><strong>القسط (prim)</strong> — مبلغ شهري تدفعه لتكون مسجَّلاً في التأمين الصحي العام GSS.</li><li><strong>حصة المشاركة (katılım payı)</strong> — مبلغ تدفعه عند تلقّي الخدمة، لا شهرياً.</li><li><strong>التأمين الخاص</strong> — بوليصة تشتريها من شركة، شرطٌ لبعض الإقامات.</li></ul><p>من يقرأ رقماً في أحد هذه الثلاثة ويظنّه في الآخر يدفع ما لا يلزمه أو يهمل ما يلزمه. وهذا بالضبط ما حدث في تغطية «انتهاء مجانية العلاج» أواخر 2025.</p><h2>حامل الكملك: لا قسط، ولا تسجيل — وحصة مشاركة عند العلاج</h2><p>القرار الرئاسي رقم 10658، المنشور في الجريدة الرسمية العدد 33091 بتاريخ 28 تشرين الثاني/نوفمبر 2025، عدّل المادة 27 من لائحة الحماية المؤقتة — <strong>وهذه المادة وحدها</strong> — ونفذ في 1 كانون الثاني/يناير 2026. وما فعله بالضبط أنّه حوّل حصة المشاركة من «قد تُؤخذ» (alınabilir) بمقدارٍ تحدّده الوزارة، إلى «تُؤخذ» (alınır) بمقادير بلاغ التطبيق الصحي نفسها المقرَّرة للمؤمَّنين في التأمين الصحي العام.</p><p><strong>ولم يفرض قسطاً ولا تسجيلاً.</strong> ولا نقول هذا استنتاجاً: كلمة «prim» (قسط) ترد صفر مرّة في لائحة الحماية المؤقتة كلّها قبل التعديل وبعده، وكذلك «tescil» (تسجيل). وعبارة «geçici koruma» ترد صفر مرّة في قانون الضمان 5510 بأكمله. والمادة 27 لا تذكر أي مبلغ بالليرة — المبالغ كلّها من بلاغ التطبيق الصحي، والقرار يستعير تعرفة التأمين الصحي العام ولا يمنح صفته.</p><p>فإن قرأت في أي مكان أنّ عليك التسجيل في التأمين الصحي العام ودفع 1,981 ليرة شهرياً أو نحو 23,782 ليرة سنوياً بوصفك حامل كملك، فذلك خطأ. المبلغ موجود فعلاً لكنّه يخصّ فئة أخرى، كما في الجدول أدناه.</p><h2>ما تدفعه فعلاً عند العلاج — أرقام تموز 2026</h2><table><thead><tr><th>أين راجعت</th><th>حصة المعاينة</th></tr></thead><tbody><tr><td>طبيب الأسرة ومراكز المرحلة الأولى</td><td><strong>لا شيء</strong></td></tr><tr><td>مستشفى الدولة (الدرجة الثانية الرسمية)</td><td>50 ليرة</td></tr><tr><td>مستشفيات التدريب والبحث، ومستشفيات وزارة الصحة من الدرجة الثالثة، ومستشفيات جامعات الدولة</td><td>90 ليرة</td></tr><tr><td>مستشفيات جامعات الوقف</td><td>100 ليرة</td></tr><tr><td>المستشفيات الخاصة (الدرجتان الثانية والثالثة)</td><td>100 ليرة</td></tr></tbody></table><p>وعليها معدِّلان يغيّران ما تدفعه فعلاً: إن جئت <strong>بإحالة من طبيب الأسرة</strong> (Sevk) تُحصَّل الحصة مخفَّضة بنسبة 50% — أي 25 بدل 50، و45 بدل 90، و50 بدل 100. وإن راجعت <strong>مزوّداً آخر في التخصّص نفسه خلال عشرة أيام</strong> تُزاد 30 ليرة.</p><p style="font-size:0.95em;opacity:0.85;">هذه الأرقام من المادة 1.8.1 من بلاغ التطبيق الصحي (SUT) بصيغته المعدَّلة بالجريدة الرسمية في 1 تموز/يوليو 2026 العدد 33297. وننبّه إلى أمر يوقع كثيرين: صفحة الشرح على موقع SGK نفسه ما زالت تعرض أرقام ما قبل تموز (26 و60 ليرة) — وهي أقلّ من النافذ بنحو النصف. المرجع هو النصّ المدمج على mevzuat.gov.tr لا صفحة الشرح.</p><p><strong>والدواء حسابه منفصل عن المعاينة:</strong> تدفع حصةً من ثمن الدواء قدرها 10% لمن يتقاضى دخلاً أو راتباً من المؤسسة و20% لغيرهم، ويُضاف بدل وصفة ثابت قدره 3.76 ليرة حتى ثلاث علب (شاملةً الثالثة) و1.25 ليرة عن كل علبة بعدها. ولهذا يبدو مبلغ الصيدلية أكبر ممّا تتوقّع: هو يجمع بدل الوصفة وحصة الدواء وحصة المعاينة في دفعة واحدة.</p><p><strong>وما لا تُؤخذ عنه حصة أصلاً:</strong> الطوارئ (عدا ما يُفوتَر تحت بند «المنطقة الخضراء» 520.021)، وإصابات العمل والأمراض المهنية، ومراجعة التخصّص المطابق لمرض مزمن مدرج في القائمة EK-1/A ما لم يُشخَّص في الزيارة نفسها تشخيصٌ آخر غير مدرج. واللقاحات مستثناة بنصٍّ صريح في لائحة الحماية المؤقتة: «Aşılar hariç olmak kaydıyla».</p><h2>ومن يعجز عن الدفع؟</h2><p>نصّت المادة 27/1-(ب) بصيغتها الجديدة على أنّ من يُثبَت أنّه لا يملك القدرة على الدفع (ödeme gücü bulunmadığı tespit edilen) تُعاد إليه حصص المشاركة التي دفعها. والتحديد ليس بيد مديرية الهجرة في ولايتك: تجريه <strong>وزارة الأسرة والخدمات الاجتماعية بالتنسيق مع رئاسة إدارة الهجرة</strong>، ويتولّى <strong>صندوق التضامن والتكافل الاجتماعي (SYDV)</strong> في منطقتك ردّ المبالغ.</p><p><strong>وأهمّ كلمة في النصّ كلمة واحدة: «talepleri halinde» — عند طلبهم.</strong> الردّ ليس تلقائياً. فمن ينطبق عليه الوصف ولا يتقدّم بطلب لا يُعاد إليه شيء. واحتفظ بإيصالاتك، فهي ما تطلب به.</p><p>ويترتّب على الفئة نفسها قيدان: لا مراجعة مباشرة للمؤسسات الصحية الخاصة إلا في الحالات الطارئة والاضطرارية (المادة 27/1-د)، ولا تُقدَّم لهم خدمات لا تغطّيها المؤسسة — عدا اللقاحات (الفقرة السادسة).</p><h2>القسط الشهري: لمن هو فعلاً</h2><table><thead><tr><th>من أنت</th><th>القسط الشهري 2026</th><th>السند</th></tr></thead><tbody><tr><td><strong>حامل كملك الحماية المؤقتة</strong></td><td><strong>لا قسط ولا تسجيل</strong></td><td>المادة 27 من لائحة الحماية المؤقتة — خارج منظومة GSS كلّياً</td></tr><tr><td>مواطن تركي بلا تغطية أخرى</td><td>1,981.80 ليرة</td><td>المادة 60/1-(g) من القانون 5510 — ونصّها «vatandaşlar»، أي المواطنون</td></tr><tr><td>مواطن دخل أسرته للفرد دون ثلث الحد الأدنى</td><td><strong>صفر</strong> — الخزينة تدفع عنه</td><td>المادة 60/1-(c)(1) مع المادة 87/(c)</td></tr><tr><td>أجنبي حامل إقامة اختار التسجيل</td><td>7,927.20 ليرة</td><td>المادة 60/1-(d): 12% من ضعف الحد الأدنى (66,060)</td></tr><tr><td>طالب أجنبي</td><td>1,321.20 ليرة</td><td>المادة 60/الفقرة السابعة: 12% من ثلث الحد الأدنى (11,010)</td></tr></tbody></table><p>الحد الأدنى الإجمالي للأجور في 2026 هو 33,030 ليرة، وعليه تُبنى كل الأرقام أعلاه. ونسبة المواطن رُفعت من 3% إلى 6% بالقرار الرئاسي رقم 10602 المنشور في الجريدة الرسمية يوم 21 تشرين الثاني/نوفمبر 2025 العدد 33084، ونفاذه من 1 كانون الأول/ديسمبر 2025 — وهو قرارٌ آخر غير القرار 10658 الذي يخصّ الحماية المؤقتة. تجاور القرارين في التوقيت هو ما ولّد الخلط.</p><p><strong>ونقطة يخطئ فيها أكثر ما يُكتب:</strong> إتمام سنة إقامة لا يجعل التسجيل إجبارياً ولا تلقائياً. كان تلقائياً حتى 2013، ثم عدّلت المادة 61/1-(ج) من القانون 5510 الحكم فصار الأجنبي «يُعدّ مؤمَّناً اعتباراً من اليوم التالي لتاريخ الطلب» — أي بطلبٍ منه هو. فمن لم يتقدّم لا يتراكم عليه شيء تحت هذا البند، لكنّه يبقى بلا تغطية حكومية وعليه أن يستوفي شرط التأمين في الإقامة ببوليصة خاصة. والطالب الأجنبي مهلته ثلاثة أشهر من بدء العام الدراسي.</p><h2>الفرق بين SGK و GSS</h2><p>SGK (Sosyal Güvenlik Kurumu) هي مؤسسة الضمان الاجتماعي — المظلّة التي تضمّ التقاعد والعجز والتأمين الصحي معاً. و GSS (Genel Sağlık Sigortası) هو الجزء الصحي منها وحده. فإن كنت موظفاً مسجَّلاً، صاحب العمل يسجّلك في SGK وتشمل تغطيتك الصحية ولا تدفع قسط GSS منفصلاً. وإن لم تكن، فالقسط الصحي وحده هو ما يُبحث.</p><h2>التأمين الخاص للإقامة</h2><p>القانون التركي ينظّم <strong>تغطية</strong> هذه البوليصة ولا يحدّد <strong>سعرها</strong>. فالحدّ الأدنى للتغطية مقرَّر في تعميم هيئة تنظيم التأمين رقم 2024/34 النافذ من 1 نيسان/أبريل 2025: 15,000 ليرة سنوياً للعلاج في العيادات الخارجية، و150,000 ليرة للعلاج بالإقامة في المستشفى، و250,000 ليرة في مستشفيات القائمة Ek-1، وبلا سقف لدى المؤسسات المتعاقدة. وأي بوليصة تُعرض عليك بأقلّ من ذلك لا تصلح للإقامة. والقسط يُدفع دفعةً واحدة مقدَّماً بنصّ التعميم.</p><p>أمّا السعر فيختلف بحسب العمر والشركة والمدّة ولا يوجد له رقم رسمي منشور — فاطلب عرضاً مكتوباً وقارن. ولا تعتمد جداول الأسعار المتداولة، فأكثرها منقول عن سنوات كان فيها الحدّ الأدنى للتغطية 2,000 ليرة لا 15,000.</p><p><strong>وقبل أن تشتري:</strong> إدارة الهجرة تقبل <strong>وثيقة التغطية من SGK</strong> (provizyon belgesi) بديلاً عن البوليصة الخاصة. فمن كان مؤمَّناً عبر عمله لا يحتاج شراءها أصلاً.</p><h2>الاستعلام عن دين GSS</h2><p>ادخل e-Devlet وابحث عن «GSS Borç Sorgulama» أو «SGK GSS Borç Dökümü». وإن ظهر عليك دين وأنت تحمل كملك الحماية المؤقتة فهو خطأ في السجل لا التزام عليك، وموضعه مراجعة SGK لتصحيح القيد — لا الدفع.</p><p style="margin-top:1.2rem;">وللتفصيل: <a href="/article/syria-temporary-protection-health-2026">حصة المشاركة الصحية للحماية المؤقتة</a> • <a href="/article/kimlik-ilac-recete-katilim-payi-sgk-teb-2026">كم تدفع في الصيدلية</a> • <a href="/article/gss-premium-2026-foreigners-syrians">قسط GSS للأجانب</a> • <a href="/article/gss-debt-inquiry">الاستعلام عن دين GSS</a></p>', steps = ARRAY['ابدأ بسؤال واحد: أي وثيقة تحمل؟ كملك حماية مؤقتة، أم إقامة، أم أنت موظف مسجَّل في الضمان؟ الجواب يحدّد كل ما بعده.', 'إن كنت حامل كملك: لا تسجّل في التأمين الصحي العام ولا تدفع قسطاً شهرياً — لا وجود لهذا الالتزام في النصّ. تدفع حصة مشاركة عند العلاج فقط.', 'ابدأ العلاج من طبيب الأسرة: معاينته بلا حصة، وإحالته تخفّض حصة المستشفى إلى النصف.', 'إن كنت لا تقدر على الدفع: تقدّم بطلب إلى صندوق التضامن والتكافل الاجتماعي (SYDV) في منطقتك لاسترداد ما دفعته — الردّ لا يقع تلقائياً بل «عند الطلب».', 'إن كنت أجنبياً حامل إقامة وأتممت سنة: التسجيل في GSS اختيارك أنت بطلب، وبعده يستحقّ 7,927.20 ليرة شهرياً. فوازن بينه وبين بوليصة خاصة قبل أن تتقدّم.', 'إن كنت طالباً أجنبياً: قدّم طلب GSS خلال ثلاثة أشهر من بدء العام الدراسي عبر خدمة «Yabancı Uyruklu Öğrencilerin GSS Başvurusu» على e-Devlet — قسطك 1,321.20 لا 7,927.20.', 'إن كنت موظفاً مسجَّلاً: صاحب العمل يدفع ضمانك وتغطيتك الصحية ضمنه — لا تدفع GSS منفصلاً. وتحقّق من التسجيل ببيان «SGK Hizmet Dökümü» لا بكلام صاحب العمل.', 'افحص دينك دورياً عبر e-Devlet. وإن ظهر دين GSS على حامل كملك فهو خطأ قيد يُصحَّح في SGK، لا مبلغ يُدفع.']::text[], tips = ARRAY['حامل الكملك لا يدفع قسطاً شهرياً: كلمتا «قسط» و«تسجيل» تردان صفر مرّة في لائحة الحماية المؤقتة.', 'مبلغ 1,981.80 ليرة يخصّ المواطن الذي لا تغطية له — ونصّ المادة يقول «vatandaşlar» صراحةً.', 'أرقام حصة المعاينة تغيّرت في 1 تموز 2026؛ وصفحة الشرح على موقع SGK نفسه ما زالت تعرض القديمة.', 'إحالة طبيب الأسرة توفّر نصف حصة المعاينة — وهي أسهل توفير في المنظومة كلّها.', 'استرداد المبالغ لمن لا يقدر على الدفع «عند الطلب» فقط — من لا يطلب لا يُعاد إليه شيء.', 'مراجعة مزوّد آخر في التخصّص نفسه خلال عشرة أيام تضيف 30 ليرة — انتظر أو خذ إحالة.', 'لا تشترِ تأميناً خاصاً قبل أن تسأل: إدارة الهجرة تقبل وثيقة تغطية SGK بديلاً عنه.', 'التسجيل في GSS للأجنبي اختياري بطلب منذ 2013، لا تلقائي بعد سنة — والفرق مالٌ كثير.']::text[], documents = ARRAY['بطاقة الحماية المؤقتة (الكملك) أو وثيقة الإقامة', 'رقم الأجنبي المكوّن من 11 خانة', 'حساب e-Devlet مفعّل — للاستعلام والتقديم', 'إيصالات حصص المشاركة التي دفعتها — هي ما تطلب به الاسترداد', 'وثيقة الطالب — إن كنت طالباً أجنبياً تتقدّم لـGSS']::text[],
    fees = 'حامل الكملك: لا قسط شهري. حصة المعاينة اعتباراً من 1 تموز 2026: لا شيء عند طبيب الأسرة، و50 ليرة في مستشفى الدولة، و90 في مستشفيات التدريب والبحث وجامعات الدولة، و100 في الخاصة وجامعات الوقف؛ تُخفَّض 50% بإحالة، وتُزاد 30 ليرة عند مراجعة مزوّد آخر في التخصّص نفسه خلال عشرة أيام. الدواء: 10% أو 20% من ثمنه، مع بدل وصفة 3.76 ليرة حتى ثلاث علب و1.25 عن كل علبة بعدها. القسط الشهري لمن يلزمه: 1,981.80 للمواطن، و7,927.20 للأجنبي المسجَّل، و1,321.20 للطالب الأجنبي.', warning = 'لا تدفع قسطاً شهرياً للتأمين الصحي العام بوصفك حامل كملك — لا وجود لهذا الالتزام في النصّ، ومبلغ 1,981.80 ليرة يخصّ فئة أخرى. وفي المقابل لا تفترض أنّ العلاج بقي مجانياً: منذ 1 كانون الثاني 2026 تُؤخذ حصة مشاركة عند كل خدمة. ومن لا يقدر على الدفع لا يُعاد إليه شيء ما لم يتقدّم بطلب إلى صندوق التضامن في منطقته.', source = 'لائحة الحماية المؤقتة م.27 معدَّلة بالقرار الرئاسي 10658 (ج.ر 33091، 28/11/2025) + بلاغ التطبيق الصحي SUT م.1.8.1 معدَّلاً في 1/7/2026 (ج.ر 33297) + القانون 5510 م.60 و80 و81 و87 — mevzuat.gov.tr', last_update = CURRENT_DATE
WHERE slug = 'sgk-gss-health-insurance-turkey-2026';

UPDATE articles SET
    title = 'قسط GSS 2026: 1,981.80 للمواطن و7,927.20 للأجنبي و1,321.20 للطالب — وحامل الكملك خارج المنظومة',
    details = replace(replace(replace(replace(replace(replace(replace(replace(details, '<strong>0 ل.ت — مستثنون</strong>', '<strong>لا قسط ولا تسجيل</strong>'), 'يستفيدون عبر منظومة الكملك مجاناً', 'خارج منظومة GSS — وحصة مشاركة عند كل خدمة منذ 1/1/2026'), 'يحصلون على الرعاية الصحية في المستشفيات الحكومية مجاناً عبر منظومة الحماية المؤقتة (Geçici Koruma Sağlık Hizmeti) وليس عبر SGK/GSS.', 'تغطيتهم عبر منظومة الحماية المؤقتة (Geçici Koruma Sağlık Hizmeti) لا عبر SGK/GSS — لكنّها لم تعد مجانية: منذ 1/1/2026 تُؤخذ حصة مشاركة عند تلقّي الخدمة.'), '<li>✅ بطاقة الكملك سارية = رعاية صحية مجانية في مستشفيات الدولة</li>', '<li>✅ بطاقة الكملك سارية = تغطية عبر المادة 27 من لائحة الحماية المؤقتة، لا عبر GSS</li>'), '<li>✅ الفحوصات والعمليات الأساسية مجانية</li>', '<li>⚠️ ولم تعد مجانية: حصة معاينة 50 ليرة في مستشفى الدولة و90 في مستشفيات التدريب والبحث و100 في الخاص — ولا شيء عند طبيب الأسرة (نافذ من 1/7/2026)</li>'), '<li>✅ الأدوية مدعومة (نسبة كبيرة منها مجانية)</li>', '<li>⚠️ والدواء تدفع منه حصة 10% أو 20% مع بدل وصفة 3.76 ليرة حتى ثلاث علب</li>'), '<p>للأجانب أن يستفيدوا من GSS — وأن يكونوا ملزَمين به — يجب توفّر:</p>', '<p>لكي يستطيع الأجنبي التسجيل في GSS — والتسجيل بطلبٍ منه لا إلزاماً عليه — يجب توفّر:</p>'), '<li>الإقامة في تركيا أكثر من سنة بدون انقطاع</li>', '<li>إتمام أكثر من سنة إقامة متواصلة — وهي شرط أهلية لا سبب تسجيل تلقائي: تنصّ المادة 61/1-(ج) من القانون 5510، بتعديل 2013، على أنّه «يُعدّ مؤمَّناً اعتباراً من اليوم التالي لتاريخ الطلب». فمن لم يطلب لا يتراكم عليه شيء</li>') || '<div style="background:#fff7ed;border-right:4px solid #ea580c;padding:14px 18px;margin:18px 0;"><p style="margin:0 0 8px;"><strong>تصحيح — ما تغيّر في 1 كانون الثاني/يناير 2026</strong></p><p style="margin:0 0 8px;">كانت هذه الصفحة تقول إنّ حامل الكملك «مستثنى» وإنّ العلاج مجاني. الشطر الأول صحيح والثاني لم يعد كذلك. القرار الرئاسي رقم 10658 (الجريدة الرسمية 33091، 28/11/2025) عدّل المادة 27 من لائحة الحماية المؤقتة فصارت حصة المشاركة تُؤخذ وجوباً بمقادير بلاغ التطبيق الصحي.</p><p style="margin:0 0 8px;">فالدقيق أن يقال: لا قسط شهري ولا تسجيل في GSS — وهذا لم يتغيّر — لكن عند كل خدمة صحية حصة مشاركة. واعتباراً من 1 تموز/يوليو 2026 هي: لا شيء عند طبيب الأسرة، و50 ليرة في مستشفى الدولة، و90 في مستشفيات التدريب والبحث وجامعات الدولة، و100 في المستشفيات الخاصة — تُخفَّض إلى النصف بإحالة من طبيب الأسرة.</p><p style="margin:0;">ومن يُثبَت عجزه عن الدفع تُعاد إليه المبالغ عبر صندوق التضامن في منطقته <strong>عند طلبه</strong> لا تلقائياً. التفصيل في <a href="/article/syria-temporary-protection-health-2026">صفحة حصة المشاركة</a>.</p></div>',
    steps = ARRAY['قسط المواطن التركي 2026: 1,981.80 ليرة شهرياً (6% من 33,030) — المادة 60/1-(g) من القانون 5510.', 'قسط الأجنبي حامل الإقامة: 7,927.20 ليرة شهرياً (12% من 66,060) — المادة 60/1-(d).', 'قسط الطالب الأجنبي: 1,321.20 ليرة شهرياً (12% من ثلث الحد الأدنى) — المادة 60/الفقرة السابعة.', 'حامل كملك الحماية المؤقتة: لا قسط ولا تسجيل — لكن حصة مشاركة عند كل خدمة منذ 1/1/2026.', 'الموظف المسجَّل في SGK 4A: لا يدفع GSS — تغطيته ضمن ضمانه، وصاحب العمل هو من يدفع.', 'تسجيل الأجنبي اختياري بطلب بعد إتمام سنة إقامة (المادة 61/1-ج، تعديل 2013) — لا تلقائي.', 'الدفع: e-Devlet أو البنوك المتعاقدة أو تطبيق e-SGK.']::text[], tips = ARRAY['الأرقام الثلاثة (1,981.80 و7,927.20 و1,321.20) كلّها أقساط شهرية — ولا واحد منها على حامل الكملك.', 'إتمام سنة إقامة لا يسجّلك تلقائياً: التسجيل بطلب منك منذ تعديل 2013، وقبل الطلب لا دين عليك.', 'إن ظهر دين GSS على حامل كملك فهو خطأ قيد يُصحَّح في SGK لا مبلغ يُدفع.', 'قارن قسط 7,927.20 شهرياً ببوليصة خاصة قبل أن تتقدّم بطلب GSS — الفرق كبير في أغلب الأعمار.', 'للأجانب المسجَّلين لا مهلة ستّين يوماً: يشترط ألّا يكون عليك دين أقساط يوم مراجعتك (م.67/1-ج).', 'احتفظ بإيصالات الدفع — تُطلب عند تجديد الإقامة.']::text[], fees = 'قسط GSS الشهري 2026: المواطن 1,981.80 ليرة • الأجنبي حامل الإقامة 7,927.20 • الطالب الأجنبي 1,321.20 • حامل كملك الحماية المؤقتة: لا قسط ولا تسجيل، وحصة مشاركة عند الخدمة (50 ليرة في مستشفى الدولة، 100 في الخاص، اعتباراً من 1/7/2026).', warning = 'لا يُسجَّل الأجنبي في GSS تلقائياً: التسجيل بطلب منه بعد سنة إقامة، وبعده يتراكم القسط حتى ينتهي التأمين. وحامل كملك الحماية المؤقتة خارج المنظومة قانوناً فلا يتراكم عليه دين GSS — لكنّه يدفع حصة مشاركة عند العلاج منذ 1 كانون الثاني 2026.',
    source = 'القانون 5510 م.60 و80 و81 و87 + القرار الرئاسي 10602 (ج.ر 33084، 21/11/2025) — mevzuat.gov.tr و sgk.gov.tr',
    last_update = CURRENT_DATE
WHERE slug = 'gss-premium-2026-foreigners-syrians';

UPDATE articles SET fees = replace(fees, 'خدمات الحماية المؤقتة (تسجيل، تحديث بيانات، علاج، تعليم) مجانية للمسجّلين.', 'خدمات التسجيل وتحديث البيانات والتعليم مجانية للمسجّلين. أمّا العلاج فلم يعد كذلك: منذ 1 كانون الثاني 2026 تُؤخذ حصة مشاركة عند الخدمة (50 ليرة في مستشفى الدولة، ولا شيء عند طبيب الأسرة).'), last_update = CURRENT_DATE
WHERE slug = 'syrians-statistics-turkey-2026' AND fees LIKE '%خدمات الحماية المؤقتة (تسجيل، تحديث بيان%';

UPDATE articles SET fees = replace(fees, 'خدمات الحماية المؤقتة (الصحة، التعليم، التسجيل) كلها مجانية للمسجّلين.', 'خدمات التسجيل والتعليم مجانية للمسجّلين. أمّا الصحة فمنذ 1 كانون الثاني 2026 تُؤخذ عنها حصة مشاركة عند تلقّي الخدمة.'), last_update = CURRENT_DATE
WHERE slug = 'syria-registration-freeze-turkey' AND fees LIKE '%خدمات الحماية المؤقتة (الصحة، التعليم، ا%';

UPDATE articles SET fees = replace(fees, 'الحجز عبر MHRS مجاني تماماً • الكشف مجاني للسوريين تحت الكملك ولأصحاب SGK • الأدوية مدعومة لمن لديه تأمين ساري.', 'الحجز عبر MHRS مجاني تماماً • أمّا الكشف فتُؤخذ عنه حصة مشاركة منذ 1/1/2026: لا شيء عند طبيب الأسرة، و50 ليرة في مستشفى الدولة، و100 في الخاص (اعتباراً من 1/7/2026)، وتُخفَّض النصف بإحالة • والدواء تدفع منه حصة 10% أو 20% مع بدل وصفة 3.76 ليرة.'), last_update = CURRENT_DATE
WHERE slug = 'mhrs-guide-syrians-arabs-2026' AND fees LIKE '%الحجز عبر MHRS مجاني تماماً • الكشف مجان%';

UPDATE articles SET details = replace(details, '<li>الكشف في المستشفى الحكومي مجاني للسوريين تحت الكملك ولمن لديه SGK ساري</li>', '<li>الكشف في المستشفى الحكومي لم يعد مجانياً منذ 1/1/2026: حصة معاينة 50 ليرة في مستشفى الدولة و90 في مستشفيات التدريب والبحث و100 في الخاص — ولا شيء عند طبيب الأسرة، والإحالة منه تخفّضها إلى النصف (<a href="/article/syria-temporary-protection-health-2026">التفصيل</a>)</li>'), last_update = CURRENT_DATE
WHERE slug = 'mhrs-guide-syrians-arabs-2026' AND details LIKE '%<li>الكشف في المستشفى الحكومي مجاني للسو%';

UPDATE articles SET details = replace(details, '<li>المستشفيات الحكومية ستعالجك مجاناً (الكملك ساري)</li>', '<li>المستشفيات الحكومية ستعالجك ما دام الكملك سارياً — لكن ليس مجاناً منذ 1/1/2026: تُؤخذ حصة مشاركة عند الخدمة. وإن كانت الإصابة إصابة عمل فهي معفاة من الحصة بنصّ بلاغ التطبيق الصحي، فأبلغ الطبيب صراحةً أنّها إصابة عمل</li>'), last_update = CURRENT_DATE
WHERE slug = 'work-injury-is-kazasi-foreigners-2026' AND details LIKE '%<li>المستشفيات الحكومية ستعالجك مجاناً (%';

UPDATE articles SET
    details = replace(details, 'مستشفيات الدولة والجامعات تبلغ حصة المعاينة فيها المستوى المحدَّد رسمياً (وجّهت التقارير إلى 26 ليرة، تحقّق من الرقم الرسمي الحالي على المصدر لأنه يتغيّر سنوياً)؛ المستشفيات الخاصة أعلى (وُجّه إلى 60 ليرة، تحقّق من الرقم الرسمي الحالي).', 'حصة المعاينة محدَّدة بالمادة 1.8.1 من بلاغ التطبيق الصحي، وقد عُدِّلت في 1 تموز/يوليو 2026 (الجريدة الرسمية العدد 33297) فصارت: 50 ليرة في مستشفى الدولة من الدرجة الثانية، و90 ليرة في مستشفيات التدريب والبحث وفي مستشفيات وزارة الصحة من الدرجة الثالثة وفي مستشفيات جامعات الدولة، و100 ليرة في مستشفيات جامعات الوقف وفي المستشفيات الخاصة من الدرجتين الثانية والثالثة. وتنبيه يوقع كثيرين: صفحة الشرح على موقع SGK نفسه ما زالت تعرض أرقام ما قبل تموز (26 و60 ليرة) — أي أقلّ من النافذ بنحو النصف؛ والمرجع هو النصّ المدمج على mevzuat.gov.tr.'),
    tips = array_replace(tips, 'الأرقام (26 و60 ليرة والنسب) قد تتغيّر سنوياً؛ تحقّق دائماً من الرقم الرسمي الحالي على موقع SGK قبل أن تعتمد رقماً', 'أرقام حصة المعاينة تغيّرت فعلاً في 1/7/2026 (50 و90 و100 ليرة)؛ وصفحة SGK التعريفية ما زالت تعرض القديمة'),
    fees = replace(fees, 'حصة المعاينة: مجانية عند طبيب الأسرة؛ مستشفيات الدولة والجامعات وُجّهت إلى 26 ليرة؛ المستشفيات الخاصة وُجّهت إلى 60 ليرة؛ وتُخفَّض 50% عند المراجعة بإحالة (Sevk).', 'حصة المعاينة: لا شيء عند طبيب الأسرة؛ 50 ليرة في مستشفى الدولة؛ 90 في مستشفيات التدريب والبحث وجامعات الدولة؛ 100 في الخاصة وجامعات الوقف؛ وتُخفَّض 50% بإحالة (Sevk)، وتُزاد 30 ليرة عند مراجعة مزوّد آخر في التخصّص نفسه خلال عشرة أيام (نافذ من 1/7/2026).'),
    source = 'بلاغ التطبيق الصحي SUT م.1.8.1 و1.8.2 و1.8.5 — النصّ المدمج على mevzuat.gov.tr (تعديل ج.ر 1/7/2026-33297 و31/12/2025-33124)',
    last_update = CURRENT_DATE
WHERE slug = 'kimlik-ilac-recete-katilim-payi-sgk-teb-2026';

UPDATE articles SET
    details = replace(replace(details, 'ونصّت المادة 2 على النفاذ حرفياً: «Bu Yönetmelik 1/1/2026 tarihinde yürürlüğe girer».', 'والنفاذ في 1/1/2026 ثابتٌ في جدول التعديلات الرسمي الملحق بالنصّ المدمج على mevzuat.gov.tr، وفيه السطر «28/11/2025 | 10658 | 27 | 1/1/2026» — وهو يثبت التاريخ ويثبت معه أنّ المادة 27 هي المادة الوحيدة التي مسّها القرار. ونسخة الجريدة الرسمية نفسها صورة ممسوحة بلا طبقة نصّ، فلا تُقتبس منها عبارة النفاذ حرفياً.'), 'الخطوة المحورية هي «تحديد القدرة المالية» (ödeme gücü)؛ راجع مديرية الهجرة في ولايتك أو مؤسسة التضامن الاجتماعي (SYDV) للحصول على تقييم فردي.', 'الخطوة المحورية هي «تحديد القدرة المالية» (ödeme gücü)، وتجريه <strong>وزارة الأسرة والخدمات الاجتماعية بالتنسيق مع رئاسة إدارة الهجرة</strong> — لا مديرية الهجرة في ولايتك وحدها. أمّا ردّ ما دفعته فيتولّاه <strong>صندوق التضامن والتكافل الاجتماعي (SYDV)</strong> في منطقتك، و<strong>عند طلبك أنت</strong> بنصّ «talepleri halinde» — لا تلقائياً.') || '<h3>كم تدفع فعلاً؟</h3><p>لم يذكر القرار الرئاسي أي مبلغ بالليرة — المبالغ كلّها من بلاغ التطبيق الصحي، وقد عُدِّلت في 1 تموز/يوليو 2026:</p><table><thead><tr><th>أين راجعت</th><th>حصة المعاينة</th></tr></thead><tbody><tr><td>طبيب الأسرة ومراكز المرحلة الأولى</td><td><strong>لا شيء</strong></td></tr><tr><td>مستشفى الدولة (الدرجة الثانية الرسمية)</td><td>50 ليرة</td></tr><tr><td>مستشفيات التدريب والبحث، ومستشفيات وزارة الصحة من الدرجة الثالثة، ومستشفيات جامعات الدولة</td><td>90 ليرة</td></tr><tr><td>مستشفيات جامعات الوقف</td><td>100 ليرة</td></tr><tr><td>المستشفيات الخاصة (الدرجتان الثانية والثالثة)</td><td>100 ليرة</td></tr></tbody></table><p>وعليها معدِّلان يغيّران ما تدفعه فعلاً: إن جئت <strong>بإحالة من طبيب الأسرة</strong> (Sevk) تُحصَّل الحصة مخفَّضة بنسبة 50% — أي 25 بدل 50، و45 بدل 90، و50 بدل 100. وإن راجعت <strong>مزوّداً آخر في التخصّص نفسه خلال عشرة أيام</strong> تُزاد 30 ليرة.</p><p style="font-size:0.95em;opacity:0.85;">هذه الأرقام من المادة 1.8.1 من بلاغ التطبيق الصحي (SUT) بصيغته المعدَّلة بالجريدة الرسمية في 1 تموز/يوليو 2026 العدد 33297. وننبّه إلى أمر يوقع كثيرين: صفحة الشرح على موقع SGK نفسه ما زالت تعرض أرقام ما قبل تموز (26 و60 ليرة) — وهي أقلّ من النافذ بنحو النصف. المرجع هو النصّ المدمج على mevzuat.gov.tr لا صفحة الشرح.</p><p><strong>والدواء حسابه منفصل عن المعاينة:</strong> تدفع حصةً من ثمن الدواء قدرها 10% لمن يتقاضى دخلاً أو راتباً من المؤسسة و20% لغيرهم، ويُضاف بدل وصفة ثابت قدره 3.76 ليرة حتى ثلاث علب (شاملةً الثالثة) و1.25 ليرة عن كل علبة بعدها. ولهذا يبدو مبلغ الصيدلية أكبر ممّا تتوقّع: هو يجمع بدل الوصفة وحصة الدواء وحصة المعاينة في دفعة واحدة.</p><p><strong>وما لا تُؤخذ عنه حصة أصلاً:</strong> الطوارئ (عدا ما يُفوتَر تحت بند «المنطقة الخضراء» 520.021)، وإصابات العمل والأمراض المهنية، ومراجعة التخصّص المطابق لمرض مزمن مدرج في القائمة EK-1/A ما لم يُشخَّص في الزيارة نفسها تشخيصٌ آخر غير مدرج. واللقاحات مستثناة بنصٍّ صريح في لائحة الحماية المؤقتة: «Aşılar hariç olmak kaydıyla».</p><p style="margin-top:1rem;">ولمن يريد التفصيل عند شبّاك الصيدلية: <a href="/article/kimlik-ilac-recete-katilim-payi-sgk-teb-2026">كم تدفع في الصيدلية</a>. وللمقارنة بين القسط وحصة المشاركة والتأمين الخاص: <a href="/article/sgk-gss-health-insurance-turkey-2026">دليل SGK و GSS</a>.</p>',
    fees = 'لا قسط شهري. حصة المعاينة من 1/7/2026: لا شيء عند طبيب الأسرة، 50 ليرة في مستشفى الدولة، 90 في مستشفيات التدريب والبحث وجامعات الدولة، 100 في الخاصة وجامعات الوقف؛ تُخفَّض 50% بإحالة، وتُزاد 30 ليرة عند مراجعة مزوّد آخر في التخصّص نفسه خلال عشرة أيام. الدواء 10% أو 20% مع بدل وصفة 3.76 ليرة حتى ثلاث علب و1.25 عن كل علبة بعدها.',
    last_update = CURRENT_DATE
WHERE slug = 'syria-temporary-protection-health-2026';

UPDATE articles SET
    title = 'سعر التأمين الصحي (السيكورتا) للإقامة في تركيا 2026: لا سعر رسمي — وهذا هو الحدّ الأدنى للتغطية',
    details = '<p>سؤال «كم سعر السيكورتا؟» له جواب واحد صادق: <strong>لا يحدّد القانون التركي سعراً لهذه البوليصة.</strong> هو يحدّد <strong>الحدّ الأدنى لتغطيتها</strong>، ويترك السعر للسوق. ولهذا فكلّ جدول أسعار «رسمي» تراه متداولاً ليس رسمياً، وأكثره منقول عن سنوات مضت.</p><h2>ما يحدّده القانون فعلاً: الحدّ الأدنى للتغطية</h2><p>تعميم هيئة تنظيم وإشراف التأمين (SEDDK) رقم 2024/34، النافذ من 1 نيسان/أبريل 2025، يفرض على أي بوليصة تُقدَّم لطلب إقامة أن تبلغ هذه الحدود السنوية على الأقل:</p><table><thead><tr><th>نوع العلاج</th><th>لدى المؤسسات المتعاقدة</th><th>غير المتعاقدة والمؤسسات العامة خارج القائمة Ek-1</th><th>المؤسسات العامة في القائمة Ek-1</th></tr></thead><tbody><tr><td>العيادات الخارجية (Ayakta)</td><td>15,000 ليرة</td><td>15,000 ليرة</td><td>15,000 ليرة</td></tr><tr><td>الإقامة في المستشفى (Yatarak)</td><td>بلا سقف</td><td>150,000 ليرة</td><td>250,000 ليرة</td></tr></tbody></table><p>وحصة المؤمَّن من الفاتورة داخل هذه الحدود: 20% لدى المتعاقدة و40% لدى غير المتعاقدة في العيادات الخارجية، و20% في الإقامة بالمستشفى لدى غير المتعاقدة، وصفر لدى المتعاقدة وفي مستشفيات القائمة Ek-1.</p><p><strong>وهذا هو المسطرة التي تقيس بها أي عرض:</strong> بوليصة لا تبلغ هذه الحدود لن تُقبل في طلب الإقامة مهما كان سعرها منخفضاً. ونصّ التعميم كذلك على أنّ قسط البوليصة <strong>يُدفع دفعةً واحدة مقدَّماً</strong> (peşin)، فلا تقسيط.</p><h2>لماذا حُذف جدول الأسعار الذي كان هنا</h2><p>كانت هذه الصفحة تنشر جدولاً يقول إنّ السنة الأولى تكلّف نحو 500 ليرة لمن بين 17 و25 سنة، و700 لمن بين 36 و45، و3,000 لمن بين 66 و69. تلك أرقام منتجٍ لم يعد موجوداً: حين كانت سارية كان الحدّ الأدنى للتغطية 2,000 ليرة للعيادات الخارجية و20,000 للإقامة بالمستشفى. ثم رُفع إلى 5,000 و50,000 في تعميم 2021/8، ثم إلى 15,000 و150,000 في التعميم النافذ اليوم. بوليصةٌ تغطّي سبعة أضعاف ما كانت تغطّيه لا تُباع بالسعر نفسه — والجدول كان يضلّل من يخطّط ميزانيته على أساسه.</p><p>ولم نستبدله بجدول آخر لأنّنا لم نجد للسعر مصدراً رسمياً واحداً؛ وكل ما يُنشر من أرقام إنّما هو عروض شركات تتغيّر بالعمر والمدّة والشركة. فاطلب عرضاً مكتوباً من أكثر من شركة، وقِس كلّاً منها بالجدول أعلاه.</p><h2>وقبل أن تشتري أصلاً</h2><p>إدارة الهجرة تقبل ضمن مستندات الإقامة <strong>وثيقة تغطية صادرة عن مؤسسة الضمان الاجتماعي (SGK provizyon belgesi)</strong> بديلاً عن البوليصة الخاصة. فمن كان مؤمَّناً عبر عمله، أو مسجَّلاً في التأمين الصحي العام، لا يحتاج شراء هذه البوليصة. ومدّة التأمين يجب أن تغطّي مدّة الإقامة المطلوبة كاملةً.</p><p><strong>وحامل كملك الحماية المؤقتة لا يشتري هذه البوليصة ولا تخصّه هذه الصفحة:</strong> تغطيته الصحية عبر المادة 27 من لائحة الحماية المؤقتة، وما يدفعه حصة مشاركة عند الخدمة لا قسط بوليصة — <a href="/article/syria-temporary-protection-health-2026">التفصيل هنا</a>.</p>', steps = ARRAY['حدّد أولاً هل تحتاجها: إن كنت مؤمَّناً عبر عملك أو مسجَّلاً في GSS، فوثيقة التغطية من SGK تُقبل بديلاً عن البوليصة الخاصة.', 'اطلب عرض سعر مكتوباً من أكثر من شركة — لا يوجد سعر رسمي موحّد ولا جدول حكومي للأسعار.', 'قِس كل عرض بالحدّ الأدنى النافذ: 15,000 ليرة للعيادات الخارجية و150,000 للإقامة بالمستشفى (250,000 في مستشفيات القائمة Ek-1). ما دون ذلك لا يصلح للإقامة.', 'تأكّد أن مدّة البوليصة تغطّي مدّة الإقامة المطلوبة كاملةً — لا أقلّ منها بيوم.', 'انتبه إلى أنّ القسط يُدفع دفعةً واحدة مقدَّماً بنصّ التعميم، فاحسبه كاملاً في ميزانيتك.', 'احتفظ بالبوليصة وإيصال الدفع — يُطلبان في ملف الإقامة وعند التجديد.']::text[], tips = ARRAY['لا يوجد سعر رسمي للسيكورتا: القانون ينظّم التغطية لا السعر — فأي «جدول أسعار رسمي» ليس رسمياً.', 'الحدّ الأدنى للتغطية ارتفع من 2,000 إلى 5,000 ثم إلى 15,000 ليرة — والجداول القديمة تعود لمنتجٍ زال.', 'بوليصة أرخص من السوق بكثير غالباً لا تبلغ الحدّ الأدنى، فتُرفض في طلب الإقامة.', 'اسأل عن وثيقة تغطية SGK قبل الشراء — قد توفّر عليك البوليصة كلّها.', 'حامل كملك الحماية المؤقتة لا يشتري هذه البوليصة — تغطيته عبر المادة 27 لا عبر بوليصة خاصة.']::text[],
    fees = 'لا يحدّد القانون سعراً. الحدّ الأدنى الملزم للتغطية: 15,000 ليرة سنوياً للعيادات الخارجية، و150,000 للإقامة بالمستشفى (250,000 في مستشفيات القائمة Ek-1، وبلا سقف لدى المتعاقدة). والقسط يُدفع دفعةً واحدة مقدَّماً.', warning = 'احذر جداول الأسعار المتداولة — أكثرها منقول عن سنوات كان الحدّ الأدنى للتغطية فيها 2,000 ليرة لا 15,000، فالأرقام أقلّ من الواقع بأضعاف. ولا تشترِ بوليصة قبل أن تتحقّق أنّها تبلغ الحدود أعلاه، وإلا رُفضت في طلب الإقامة وخسرت قسطها.',
    source = 'تعميم هيئة تنظيم وإشراف التأمين SEDDK رقم 2024/34 النافذ 1/4/2025 (seddk.gov.tr) + مستندات الإقامة على e-ikamet.goc.gov.tr',
    last_update = CURRENT_DATE
WHERE slug = 'أسعار-السيكورتا-الصحية-في-تركيا-لعام-2026-دليل-شامل';

UPDATE consultant_scenarios SET cost = replace(cost, 'صفر في مؤسسات الرعاية الأولية (مركز صحة العائلة)، و26 ليرة في مؤسسات الدرجة الثانية والثالثة الحكومية، و60 ليرة في مؤسسات الدرجة الثانية والثالثة الخاصة.', 'صفر عند طبيب الأسرة ومؤسسات الرعاية الأولية، و50 ليرة في مستشفى الدولة من الدرجة الثانية، و90 ليرة في مستشفيات التدريب والبحث ومستشفيات وزارة الصحة من الدرجة الثالثة ومستشفيات جامعات الدولة، و100 ليرة في المستشفيات الخاصة ومستشفيات جامعات الوقف — نافذة من 1/7/2026 (ج.ر 33297). وتُخفَّض 50% بإحالة من طبيب الأسرة، وتُزاد 30 ليرة عند مراجعة مزوّد آخر في التخصّص نفسه خلال عشرة أيام. وصفحة الشرح على موقع SGK ما زالت تعرض أرقام ما قبل تموز (26 و60) فلا تعتمدها.'), last_update = '2026-08'
WHERE id = 'daily-mhrs-booking' AND cost LIKE '%صفر في مؤسسات الرعاية الأولية (مركز%';

UPDATE consultant_scenarios SET description = replace(description, 'بدءاً من 2026، لم يعد العلاج مجانياً بالكامل لمن هم خارج نظام الضمان. يتوجب دفع "رسوم مشاركة" أو GSS إذا لم تكن مسجلاً عبر عمل. صاحب العمل ملزم بتسجيلك فور صدور الإذن.', 'بدءاً من 1/1/2026 لم يعد العلاج مجانياً لحاملي الحماية المؤقتة: تُؤخذ حصة مشاركة (katılım payı) عند تلقّي الخدمة. وهذه ليست قسط GSS ولا بديلاً عنه — حامل الحماية المؤقتة خارج منظومة GSS أصلاً فلا قسط عليه ولا تسجيل. وصاحب العمل ملزم بتسجيلك في الضمان فور صدور إذن العمل، والتسجيل عبر العمل يغطّيك صحياً.'), last_update = '2026-08'
WHERE id = 'work-sgk' AND description LIKE '%بدءاً من 2026، لم يعد العلاج مجانيا%';

UPDATE consultant_scenarios SET steps = '["صاحب العمل يسجلك في SGK خلال 30 يوماً من بدء إذن العمل.", "إذا كنت تحت الحماية المؤقتة ولا تعمل: اختبار الدخل (Gelir Testi) الخاص بـ GSS مخصص للمواطنين الأتراك ولا ينطبق عليك. الآلية التي تخصك: تدفع \"رسم المشاركة\" (katılım payı) عند تلقي الخدمة الصحية، ثم إذا ثُبتت عدم قدرتك المادية بتنسيق بين وزارة الأسرة ورئاسة الهجرة، تستردّ ما دفعته من وقف التكافل (SYDV) بناءً على طلبك (المادة 27 من لائحة الحماية المؤقتة، المعدّلة في 28/11/2025).", "إذا ثبتت عدم قدرتك المادية تُعاد إليك حصص المشاركة التي دفعتها — عبر صندوق التضامن والتكافل (SYDV) في منطقتك و«عند طلبك» لا تلقائياً. وإن لم تثبت فأنت تدفع حصة المشاركة عند كل خدمة — ولا قسط GSS شهري عليك في الحالتين.", "تابع ديون GSS عبر e-Devlet لتجنب تراكم المبالغ."]'::jsonb, last_update = '2026-08'
WHERE id = 'work-sgk';

UPDATE consultant_scenarios SET cost = replace(cost, 'مع «مساهمة» وفق SUT منذ 28/11/2025 تُستردّ ع', 'مع «حصة مشاركة» وفق SUT نفذت في 1/1/2026 — تاريخ 28/11/2025 هو تاريخ نشر القرار لا نفاذه — وتُستردّ ع'), last_update = '2026-08'
WHERE id = 'family-pregnancy-birth' AND cost LIKE '%مع «مساهمة» وفق SUT منذ 28/11/2025 %';

-- ═══════════════════════════════════════════════════════════════════════════
-- التحقّق — كل صفّ يجب أن يعود true
SELECT 'sgk-gss-health-insurance-turkey-2026' AS الصفحة, (details NOT LIKE '%23,782%' AND details NOT LIKE '%لازم يسجلوا ويدفعوا%' AND details LIKE '%33297%') AS سليمة FROM articles WHERE slug = 'sgk-gss-health-insurance-turkey-2026'
UNION ALL
SELECT 'gss-premium-2026-foreigners-syrians' AS الصفحة, (title NOT LIKE '%مستثنون%' AND details LIKE '%10658%' AND details NOT LIKE '%الفحوصات والعمليات الأساسية مجانية%') AS سليمة FROM articles WHERE slug = 'gss-premium-2026-foreigners-syrians'
UNION ALL
SELECT 'syrians-statistics-turkey-2026' AS الصفحة, (fees NOT LIKE '%علاج، تعليم) مجانية%') AS سليمة FROM articles WHERE slug = 'syrians-statistics-turkey-2026'
UNION ALL
SELECT 'syria-registration-freeze-turkey' AS الصفحة, (fees NOT LIKE '%(الصحة، التعليم، التسجيل) كلها مجانية%') AS سليمة FROM articles WHERE slug = 'syria-registration-freeze-turkey'
UNION ALL
SELECT 'mhrs-guide-syrians-arabs-2026' AS الصفحة, (fees NOT LIKE '%الكشف مجاني للسوريين%') AS سليمة FROM articles WHERE slug = 'mhrs-guide-syrians-arabs-2026'
UNION ALL
SELECT 'work-injury-is-kazasi-foreigners-2026' AS الصفحة, (details NOT LIKE '%ستعالجك مجاناً%') AS سليمة FROM articles WHERE slug = 'work-injury-is-kazasi-foreigners-2026'
UNION ALL
SELECT 'kimlik-ilac-recete-katilim-payi-sgk-te' AS الصفحة, (details LIKE '%33297%' AND fees LIKE '%90 في مستشفيات%' AND fees NOT LIKE '%وُجّهت إلى 26 ليرة%') AS سليمة FROM articles WHERE slug = 'kimlik-ilac-recete-katilim-payi-sgk-teb-2026'
UNION ALL
SELECT 'syria-temporary-protection-health-2026' AS الصفحة, (details LIKE '%33297%' AND fees LIKE '%50 ليرة%' AND details LIKE '%talepleri halinde%') AS سليمة FROM articles WHERE slug = 'syria-temporary-protection-health-2026'
UNION ALL
SELECT 'أسعار-السيكورتا-الصحية-في-تركيا-لعام-2' AS الصفحة, (details NOT LIKE '%<td>500</td>%' AND details LIKE '%2024/34%' AND coalesce(array_length(steps,1),0) >= 3) AS سليمة FROM articles WHERE slug = 'أسعار-السيكورتا-الصحية-في-تركيا-لعام-2026-دليل-شامل'
UNION ALL
SELECT 'consultant: mhrs 50/90/100', (cost LIKE '%33297%') FROM consultant_scenarios WHERE id = 'daily-mhrs-booking'
UNION ALL
SELECT 'consultant: work-sgk no prem', (description NOT LIKE '%أو GSS إذا لم تكن%') FROM consultant_scenarios WHERE id = 'work-sgk'
UNION ALL
SELECT 'no page still says 26/60', (count(*) = 0)::boolean FROM articles
  WHERE status = 'approved' AND (fees LIKE '%وُجّهت إلى 26 ليرة%' OR details LIKE '%وُجّه إلى 60 ليرة%');
